@startuml

class Traveller {
  + name : string
  + companyName : string
  + address : string
  + reliabilityRating : float
}

class TravelPreference {
  + description : string
}

class SearchCriteria {
  + city : string
  + arrivalDate : date
  + departureDate : date
  + numberOfRooms : int
  + roomType : string
  + minimumRating : int
  + maxCostPerNight : float
}

class Booking {
  + bookingIdentifier : string
  + price : float
  + cityArea : string
  + hotelRating : int
  + cancellationDeadline : date
  + status : string
}

class SpecialOffer {
  + price : float
}

class CreditCardInfo {
  + cardNumber : string
}

class Hotel {
  + name : string
  + address : string
  + rating : int
}

class HotelChain {
  + name : string
}

class RoomType {
  + type : string
}

class Availability {
  + startDate : date
  + endDate : date
  + isFull : boolean
}

enum PaymentMethod {
  PRE_PAID
  PAID_AT_HOTEL
}

Traveller "1" -- "*" TravelPreference : has
Traveller "1" -- "*" Booking : makes
Traveller "1" -- "1" CreditCardInfo : provides
Traveller "1" -- "*" SpecialOffer : receives
Traveller "1" -- "0..1" HotelChain : belongs to

Booking "1" -- "1" PaymentMethod : uses
Booking "1" -- "1" CreditCardInfo : finalized with
Booking "*" -- "0..1" SpecialOffer : can switch to
Booking "*" -- "1" Hotel : confirmed by

Hotel "1" -- "*" Availability : announces
Hotel "1" -- "*" RoomType : offers
Hotel "1" -- "0..1" HotelChain : run by
Hotel "1" -- "1" City : located in

class City {
  + name : string
}

@enduml

